css:
/* THEME 7: SQUAREUP (Lime Green Brutalism) */
@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&display=swap');

:root { 
  --primary: #CCFF00; /* Яркий лаймовый */
  --bg-gradient: #0A0A0A; 
  --card-bg: #141414; 
  --card-dark: #0F0F0F; 
  --text-main: #FFFFFF; 
  --text-muted: #888888; 
  --border-color: #2A2A2A; 
  --radius: 8px; /* Острые углы */
  --shadow-sm: 0 4px 0px 0px rgba(204, 255, 0, 0.2); 
  --font-main: 'Space Grotesk', sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: var(--font-main); background: var(--bg-gradient); color: var(--text-main); line-height: 1.6; display: flex; flex-direction: column; min-height: 100vh; }
a { text-decoration: none; color: var(--primary); transition: 0.2s; }
a:hover { opacity: 0.7; }

.site-header { background: #0A0A0A; border-bottom: 1px solid var(--border-color); position: sticky; top: 0; z-index: 1000; }
.header-container { max-width: 1200px; margin: 0 auto; padding: 15px 20px; display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 15px; }
.logo { font-size: 1.5rem; font-weight: 700; color: #fff; text-transform: uppercase; letter-spacing: 1px; }

.search-input { padding: 10px 16px; border-radius: var(--radius); border: 1px solid var(--border-color); background: #000; color: #fff; width: 300px; font-family: inherit; font-size: 0.9rem; transition: 0.3s; }
.search-input:focus { outline: none; border-color: var(--primary); }

.header-nav { display: flex; gap: 20px; align-items: center; font-weight: 500; }
.btn-primary { background: var(--primary); color: #000; padding: 10px 20px; border-radius: var(--radius); font-weight: 700; border: none; cursor: pointer; transition: 0.2s; text-transform: uppercase; font-size: 0.85rem; }
.btn-primary:hover { background: #E0FF33; transform: translateY(-2px); box-shadow: 0 4px 0px 0px #000, 0 6px 0px 0px var(--primary); }

.layout-container { max-width: 1200px; margin: 40px auto; padding: 0 20px; display: flex; flex-direction: column; gap: 30px; flex-grow: 1; width: 100%; }
@media(min-width: 860px) { .layout-container { flex-direction: row; } }
.main-content { flex-grow: 1; width: 100%; }
@media(min-width: 860px) { .main-content { width: 72%; } }
.sidebar { width: 100%; display: flex; flex-direction: column; gap: 20px; }
@media(min-width: 860px) { .sidebar { width: 28%; } }

.card { background: var(--card-bg); border: 1px solid var(--border-color); border-radius: var(--radius); padding: 25px; transition: 0.3s; }
.card:hover { border-color: var(--primary); }
.widget-title { font-size: 1.1rem; border-bottom: 1px solid var(--border-color); padding-bottom: 12px; margin-bottom: 16px; font-weight: 700; color: #fff; text-transform: uppercase; letter-spacing: 0.5px; }

.stat-list li { display: flex; justify-content: space-between; padding: 10px 0; border-bottom: 1px solid var(--border-color); font-size: 0.95rem; }
.stat-list li:last-child { border-bottom: none; }

.post-list { display: grid; gap: 16px; }
.post-item { background: var(--card-bg); border: 1px solid var(--border-color); border-radius: var(--radius); padding: 25px; transition: 0.2s; }
.post-item:hover { border-color: var(--primary); }
.post-title { font-size: 1.3rem; font-weight: 700; margin-bottom: 8px; color: #fff; }
.post-meta { display: flex; gap: 16px; font-size: 0.85rem; color: var(--text-muted); margin-top: 10px; }

.message-block { background: var(--card-bg); border: 1px solid var(--border-color); border-radius: var(--radius); margin-bottom: 20px; display: flex; flex-direction: column; transition: 0.3s; }
.message-block:hover { border-color: #333; }
@media(min-width: 640px) { .message-block { flex-direction: row; } }
.user-panel { background: var(--card-dark); padding: 20px; display: flex; align-items: center; border-bottom: 1px solid var(--border-color); }
@media(min-width: 640px) { .user-panel { width: 160px; border-bottom: none; border-right: 1px solid var(--border-color); flex-direction: column; text-align: center; flex-shrink: 0; } }
.user-panel img { width: 60px; height: 60px; border-radius: 4px; margin-bottom: 12px; filter: grayscale(100%); }
.message-content { padding: 25px; flex-grow: 1; }
.message-header { display: flex; justify-content: space-between; padding-bottom: 10px; margin-bottom: 15px; font-size: 0.85rem; color: var(--text-muted); border-bottom: 1px dashed var(--border-color); }

.badge { background: #000; color: var(--primary); font-size: 0.75rem; padding: 4px 10px; border-radius: 4px; font-weight: 700; border: 1px solid var(--primary); display: inline-block; text-transform: uppercase; }

.pagination { display: flex; justify-content: flex-start; gap: 10px; margin-top: 40px; }
.page-link { padding: 8px 16px; border: 1px solid var(--border-color); background: var(--card-bg); border-radius: var(--radius); font-weight: 600; color: #fff; transition: 0.2s; }
.page-link:hover { border-color: var(--primary); color: var(--primary); }
.page-link.active { background: var(--primary); color: #000; border-color: var(--primary); }

.site-footer { background: var(--card-bg); padding: 40px 20px; border-top: 1px solid var(--border-color); margin-top: auto; font-size: 0.9rem; color: var(--text-muted); }
.footer-container { max-width: 1200px; margin: 0 auto; display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 30px; }
